def min_operations(a, b):
    d = abs(a - b)
    if d == 0:
        return 0

    low, high = 1, d
    while low < high:
        mid = (low + high) // 2
        if mid * (mid + 1) // 2 < d:
            low = mid + 1
        else:
            high = mid

    return low

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1
    results = []

    for _ in range(t):
        a = int(data[index])
        index += 1
        b = int(data[index])
        index += 1
        results.append(min_operations(a, b))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
